/**
 * vitest stub for `$app/env/public`.
 *
 * The real module is generated by the SvelteKit plugin from src/env.ts and,
 * for non-static variables, is populated by the runtime when the app starts.
 * Under vitest (jsdom, no server) nothing populates it, so it is aliased to
 * this stub in `vitest.config.ts`. Deliberately unset: a test must not
 * depend on ambient configuration. Code that needs to assert on a *value*
 * tests the pure resolver (`#lib/source.ts` → `resolveSourceUrl`) with an
 * explicit argument.
 */
export const PUBLIC_SOURCE_URL: string | undefined = undefined;
